    // dp[x] initially = p^x mod MOD.
    // For step in 1..k:
    //   new_dp[x] = (sum_{y=0}^{x} dp[y]) * inv(x+1) mod MOD
    //   dp = new_dp
    // Answer for this prime factor is dp[e].
    //
    // The total answer is the product of dp_i[e_i] for all prime factors.

    ll ans = 1;

    for (auto &factor : factors) {
        ll p = factor.first;
        int e = factor.second;

        // dp[x] = expected value of p^{X_t} given X_0 = x, after t steps
        // Initially t=0: dp[x] = p^x
        vector<ll> dp(e + 1);
