#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

#define MOD 1000000007

ll modpow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

ll modinv(ll a, ll mod) {
    return modpow(a, mod - 2, mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    // Factorize n
    vector<pair<ll, int>> factors;
    ll temp = n;
    for (ll i = 2; i * i <= temp; i++) {
        if (temp % i == 0) {
            int cnt = 0;
            while (temp % i == 0) {
                cnt++;
                temp /= i;
            }
            factors.push_back({i, cnt});
        }
    }
    if (temp > 1) {
        factors.push_back({temp, 1});
    }

    int m = factors.size();

    // For each prime factor p_i with exponent a_i, we need to compute:
    // E_i = sum_{j=0}^{a_i} (p_i^j) * P(X_i = j)
    // where X_i is the exponent of p_i after k steps.
    // The transition: from exponent e, we pick a divisor uniformly.
    // The new exponent is uniformly chosen from {0, 1, ..., e}.
    // So if current exponent is e, next exponent is uniform on [0, e].
    //
    // Let dp[t][e] = probability that after t steps, the exponent is e.
    // dp[0][a_i] = 1, dp[0][e] = 0 for e != a_i.
    // dp[t+1][j] = sum_{e=j}^{a_i} dp[t][e] / (e + 1)
    //
    // We need to compute for each prime factor the expected value of p_i^{X_i} after k steps.
    // Then the total expected value is the product over all prime factors.

    // For each prime factor, compute the expected value of p^X after k steps.
    // Let f(t, e) = probability that after t steps, exponent is e, starting from a_i.
    // We want sum_{e=0}^{a_i} p^e * f(k, e)

    // Since a_i can be up to about 50 (since 2^50 > 1e15), and k up to 10000,
    // we can do DP for each prime factor.

    ll ans = 1;

    for (auto &factor : factors) {
        ll p = factor.first;
        int a = factor.second;

        // dp[e] = probability that current exponent is e
        vector<ll> dp(a + 1, 0);
        dp[a] = 1;

        for (int step = 0; step < k; step++) {
            vector<ll> new_dp(a + 1, 0);
            for (int e = 0; e <= a; e++) {
                if (dp[e] == 0) continue;
                // From exponent e, next exponent is uniform on {0, 1, ..., e}
                // So probability of going to j (where j <= e) is 1/(e+1)
                ll prob = dp[e] * modinv(e + 1, MOD) % MOD;
                for (int j = 0; j <= e; j++) {
                    new_dp[j] = (new_dp[j] + prob) % MOD;
                }
            }
            dp = new_dp;
