    // and k up to 1e4, we can do O(k * e^2) per prime factor.

    ll result = 1;

    for (auto& [p, e] : factors) {
        // dp[i] = E[p^X_t | X_0 = i] for current t
        vector<ll> dp(e + 1);
        for (int i = 0; i <= e; i++) {
