                // new_dp[i] = (1/(i+1)) * sum_{j=0}^{i} dp[j]
                // = (1/(i+1)) * prefix[i+1]
                ll sum = prefix[i + 1];
                ll inv = modinv(i + 1);
                new_dp[i] = sum * inv % mod;
            }
            dp = new_dp;
        }

        // The contribution of this prime factor is dp[e]
        result = result * dp[e] % mod;
    }

    cout << result << endl;

