        // Base case: i=0
        for (int j = 0; j <= e; j++) {
            dp[0][j] = modpow(p, j, MOD);
        }

        // Transition
        for (int i = 1; i <= k; i++) {
            // h[i][j] = (1/(j+1)) * sum_{m=0}^{j} h[i-1][m]
            // We can compute prefix sums
            vector<ll> prefix(e + 1, 0);
            prefix[0] = dp[i - 1][0];
            for (int j = 1; j <= e; j++) {
                prefix[j] = (prefix[j - 1] + dp[i - 1][j]) % MOD;
            }
            for (int j = 0; j <= e; j++) {
                ll sum = prefix[j];
                ll inv = modinv(j + 1, MOD);
                dp[i][j] = sum * inv % MOD;
            }
        }

        ans = ans * dp[k][e] % MOD;
    }

    cout << ans << endl;

    return 0;
}
