#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1e9 + 7;

ll modpow(ll a, ll b, ll mod) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

ll modinv(ll a, ll mod) {
    return modpow(a, mod - 2, mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    // Factorize n
    vector<pair<ll, int>> factors;
    ll temp = n;
    for (ll i = 2; i * i <= temp; i++) {
        if (temp % i == 0) {
            int cnt = 0;
            while (temp % i == 0) {
                cnt++;
                temp /= i;
            }
            factors.push_back({i, cnt});
        }
    }
    if (temp > 1) {
        factors.push_back({temp, 1});
    }

    int m = factors.size();

    // dp[i][j] = probability that after k steps, the exponent of the i-th prime is j
    // We use modular arithmetic.
    // The expected value is product over primes of (sum_{j=0}^{e_i} j * p_i^j * prob[i][j])
    // But actually, the expected value of the number is the product of expected values of each prime power?
    // No, the number is product of p_i^{e_i}, and the exponents are not independent in general?
    // Wait, the process: at each step, we pick a divisor uniformly. A divisor of v = prod p_i^{a_i} is prod p_i^{b_i} where 0 <= b_i <= a_i.
    // The choice of each b_i is independent? No, the divisor is chosen uniformly from all divisors.
    // The number of divisors is prod (a_i + 1). Each combination (b_1, ..., b_m) with 0<=b_i<=a_i is equally likely.
    // So the exponents are independent in the sense that the joint probability is product of individual probabilities?
    // Yes! Because the number of divisors is the product of (a_i+1), and each tuple (b_1,...,b_m) corresponds to exactly one divisor.
    // So the probability of a specific tuple is 1/prod(a_i+1).
    // This means the exponents evolve independently? Not exactly, because the state is the tuple of exponents.
    // But the transition: from state (a_1,...,a_m), we go to (b_1,...,b_m) with probability 1/prod(a_i+1) for each valid b_i.
    // This is a product structure. The Markov chain on the product space has transitions that factor.
    // Specifically, the probability of transitioning from a_i to b_i for each prime i is 1/(a_i+1), and these are independent across primes.
    // Therefore, the exponents for different primes evolve independently!
    // So we can compute for each prime separately the expected value of p^X after k steps, where X is the exponent.
    // Then the total expected value is the product of these individual expected values.

    // For a single prime with initial exponent e, let f(t, j) be the probability that after t steps, the exponent is j.
    // Initially, f(0, e) = 1, f(0, j) = 0 for j != e.
    // Transition: from exponent a, we go to exponent b (0<=b<=a) with probability 1/(a+1).
    // So f(t+1, b) = sum_{a=b}^{e} f(t, a) * (1/(a+1))
    // We need to compute this for t=0..k, for each prime.

    // Since k can be up to 10^4 and e can be up to ~50 (since 2^50 > 1e15), we can do DP for each prime.
    // The maximum exponent for any prime in n is at most log2(1e15) ~ 50.

    ll ans = 1;

    for (auto &factor : factors) {
        ll p = factor.first;
        int e = factor.second;

        // dp[j] = probability that current exponent is j
        vector<ll> dp(e + 1, 0), ndp(e + 1, 0);
        dp[e] = 1;

        for (int step = 0; step < k; step++) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int a = 0; a <= e; a++) {
                if (dp[a] == 0) continue;
                // From exponent a, we can go to any b in [0, a] with probability 1/(a+1)
                ll prob = dp[a] * modinv(a + 1, MOD) % MOD;
                for (int b = 0; b <= a; b++) {
                    ndp[b] = (ndp[b] + prob) % MOD;
                }
            }
            dp = ndp;
        }

        // Now compute the expected value of p^X
        ll exp_val = 0;
        ll p_pow = 1;
        for (int j = 0; j <= e; j++) {
            exp_val = (exp_val + dp[j] * p_pow) % MOD;
            p_pow = p_pow * p % MOD;
        }

        ans = ans * exp_val % MOD;
    }

    cout << ans << endl;

    return 0;
}
