typedef long long ll;
const ll MOD = 1e9 + 7;

ll mod_pow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

ll mod_inv(ll a, ll mod) {
    return mod_pow(a, mod - 2, mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    // Factorize n
    vector<pair<ll, int>> factors;
    ll temp = n;
    for (ll i = 2; i * i <= temp; i++) {
        if (temp % i == 0) {
            int cnt = 0;
            while (temp % i == 0) {
                cnt++;
                temp /= i;
            }
            factors.push_back({i, cnt});
        }
    }
    if (temp > 1) {
        factors.push_back({temp, 1});
    }

    // For each prime factor p^e, we need to compute the expected value contribution.
    // The process is multiplicative over prime factors.
    // For a prime power p^e, the state is the exponent a (0 <= a <= e).
    // From state a, we transition to state b (0 <= b <= a) with probability 1/(a+1).
    // We want E[final value] = product over primes of E[p^{final exponent}].
    // Due to independence, we can compute for each prime factor separately.

    // Let dp[step][a] = probability that after 'step' operations, the exponent is 'a'.
    // But k can be up to 10^4 and e can be up to ~50 (since 2^50 > 1e15).
    // Actually, the maximum exponent for any prime factor of n <= 1e15 is at most 50.
    // So we can do DP for each prime factor.

    ll ans = 1;

    for (auto &factor : factors) {
        ll p = factor.first;
        int e = factor.second;

        // dp[a] = probability that current exponent is a
        // Initially, exponent is e with probability 1.
        vector<ll> dp(e + 1, 0);
        dp[e] = 1;

        for (int step = 0; step < k; step++) {
            vector<ll> new_dp(e + 1, 0);
            for (int a = 0; a <= e; a++) {
                if (dp[a] == 0) continue;
                // From exponent a, we can go to any b in [0, a] with probability 1/(a+1)
                ll prob = dp[a] * mod_inv(a + 1, MOD) % MOD;
                for (int b = 0; b <= a; b++) {
                    new_dp[b] = (new_dp[b] + prob) % MOD;
                }
            }
            dp = new_dp;
        }

        // Now compute E[p^exponent] = sum_{a=0}^{e} dp[a] * p^a
        ll exp_val = 0;
        for (int a = 0; a <= e; a++) {
            if (dp[a] == 0) continue;
            ll p_pow = mod_pow(p % MOD, a, MOD);
            exp_val = (exp_val + dp[a] * p_pow) % MOD;
        }

        ans = ans * exp_val % MOD;
    }

    cout << ans << endl;

    return 0;
}
