    // Let E[e][k] be the expected exponent after k steps starting from exponent e.
    // E[e][0] = e
    // E[e][k] = (1/(e+1)) * sum_{j=0}^{e} E[j][k-1]
    //
    // We can precompute the expected values for exponents up to max_e.
    // max_e is the maximum exponent among all prime factors.

    int max_e = 0;
    for (auto &f : factors) {
        max_e = max(max_e, f.second);
    }

    // dp[i] will store the expected exponent after current number of steps, starting from initial exponent i.
    // We need to compute for all i from 0 to max_e, for k steps.
    // Let dp[step][i] = expected exponent after 'step' steps starting from exponent i.
    // dp[0][i] = i
    // dp[step][i] = (1/(i+1)) * sum_{j=0}^{i} dp[step-1][j]

    // We can use prefix sums to compute this efficiently.
    // Let S[step][i] = sum_{j=0}^{i} dp[step][j]
    // Then dp[step][i] = S[step-1][i] * inv(i+1)
    // And S[step][i] = S[step][i-1] + dp[step][i]

    // We only need the previous step's prefix sums to compute the current step.
    vector<ll> prev_dp(max_e + 1);
    vector<ll> prev_prefix(max_e + 1);

    // Initialize for step 0
    for (int i = 0; i <= max_e; i++) {
        prev_dp[i] = i;
    }
    prev_prefix[0] = prev_dp[0];
    for (int i = 1; i <= max_e; i++) {
        prev_prefix[i] = (prev_prefix[i-1] + prev_dp[i]) % MOD;
    }

    // Iterate for k steps
    for (int step = 1; step <= k; step++) {
        vector<ll> curr_dp(max_e + 1);
        vector<ll> curr_prefix(max_e + 1);

        for (int i = 0; i <= max_e; i++) {
            // dp[step][i] = (1/(i+1)) * sum_{j=0}^{i} dp[step-1][j]
            // sum_{j=0}^{i} dp[step-1][j] = prev_prefix[i]
            curr_dp[i] = prev_prefix[i] * mod_inv(i + 1, MOD) % MOD;

            if (i == 0) {
                curr_prefix[i] = curr_dp[i];
            } else {
                curr_prefix[i] = (curr_prefix[i-1] + curr_dp[i]) % MOD;
            }
        }

        prev_dp = curr_dp;
        prev_prefix = curr_prefix;
