    // The choices of d_i are independent of each other. So the evolution of each exponent is independent.
    // Therefore, E[product p_i^{X_i}] = product E[p_i^{X_i}].

    ll ans = 1;
    for (auto &f : factors) {
        ll p = f.first % MOD;
        int e = f.second;
        // E[p^X] where X is the random variable for the exponent after k steps, starting from e.
