        // So we need to redo the DP for each prime factor, or we can notice that the recurrence is linear.
        // Actually, the recurrence is:
        // g[step][i] = (1/(i+1)) * sum_{j=0}^{i} g[step-1][j]
        // This is a linear recurrence. If we define a vector g0 = [g[0][0], g[0][1], ..., g[0][max_e]],
        // then g[step] = M * g[step-1], where M is a fixed matrix.
        // But we can just run the DP for each prime factor separately.

        // Since max_e is at most about 50 (because 2^50 > 10^15), and k is up to 10^4,
        // and the number of distinct prime factors is at most about 15, this is efficient.

        vector<ll> dp(max_e + 1);
        vector<ll> prefix(max_e + 1);

        // Initialize for step 0: dp[i] = p^i
        for (int i = 0; i <= max_e; i++) {
            dp[i] = mod_pow(p, i, MOD);
        }
        prefix[0] = dp[0];
        for (int i = 1; i <= max_e; i++) {
            prefix[i] = (prefix[i-1] + dp[i]) % MOD;
        }

        // Iterate for k steps
        for (int step = 1; step <= k; step++) {
            vector<ll> curr_dp(max_e + 1);
            vector<ll> curr_prefix(max_e + 1);

            for (int i = 0; i <= max_e; i++) {
                curr_dp[i] = prefix[i] * mod_inv(i + 1, MOD) % MOD;

                if (i == 0) {
                    curr_prefix[i] = curr_dp[i];
                } else {
                    curr_prefix[i] = (curr_prefix[i-1] + curr_dp[i]) % MOD;
                }
            }

            dp = curr_dp;
            prefix = curr_prefix;
        }

        // The answer for this prime factor is dp[e]
        ans = ans * dp[e] % MOD;
    }

    cout << ans << endl;

    return 0;
}
